CREATE OR REPLACE FUNCTION public.sensitive_preference_sections(_old jsonb,_new jsonb) RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(array_agg(k ORDER BY k),ARRAY[]::text[]) FROM (SELECT k FROM unnest(ARRAY['assets','entities','paymentInstruments','reimbursementProfiles']) k WHERE coalesce(_old->k,'null') IS DISTINCT FROM coalesce(_new->k,'null') UNION ALL SELECT 'books.'||k FROM unnest(ARRAY['policy','rules','fieldMappings','entityAccounts','fyRecords','properties','leases','propertyCosts','assetEvents','holdings','priceOverrides','goldRate','taxProfiles','entityTaxProfiles','taxCredits','taxDeductions','salaryEvidence','gstInvoices','gstAdvances','gstFilings','loanBalances']) k WHERE coalesce(_old->'books'->k,'null') IS DISTINCT FROM coalesce(_new->'books'->k,'null')) changed; $$;